    }
    association(source = application, target = districtChapter) {
        aggregation = AggregationKind.NONE
        source { multiplicity(spec = "1") }
        target { multiplicity(spec = "1"); role = "submittedTo" }
    }
    association(source = member, target = application) {
        aggregation = AggregationKind.NONE
        source { multiplicity(spec = "0..*") }
        target { multiplicity(spec = "1"); role = "appliedFor" }
    }
    association(source = committee, target = mandate) {
