sequenceDiagram(name = "Password Reset") {
    val user = lifeline(name = "User") { isActor = true }
    val portal = lifeline(name = "Web Portal")
    val authService = lifeline(name = "Auth Service")
    val db = lifeline(name = "User DB")

    message(from = user, to = portal, label = "requestPasswordReset(email)")
    message(from = portal, to = authService, label = "lookupEmail(email)")

    alt {
        branch(guard = "[email found]") {
            message(from = authService, to = db, label = "generateResetToken()")
            message(from = db, to = authService, label = "storeToken()")
            asyncMessage(from = authService, to = db, label = "sendResetEmail()")
            reply(from = authService, to = portal, label = "success")
        }
        branch(guard = "[email not found]") {
            reply(from = authService, to = portal, label = "success")
        }
    }

    reply(from = portal, to = user, label = "notification")
}

